import { assign, setup } from 'xstate';

type Event = { type: 'chosen'; id: string } | { type: 'next' } | { type: 'submit' };
const machine = setup({
  types: { context: {} as { accountId?: string }, events: {} as Event },
  actions: {
    assignAccount: assign(({ event }) => ({
      accountId: event.type === 'chosen' ? event.id : undefined,
    })),
  },
  guards: { amountValid: ({ context }) => Boolean(context.accountId) },
}).createMachine({
  context: { accountId: undefined },
  initial: 'select',
  states: {
    select:  { on: { chosen: { target: 'amount', actions: 'assignAccount' } } },
    amount:  { on: { next:   { target: 'confirm', guard: 'amountValid' } } },
    confirm: { on: { submit: 'done' } },
    done:    { type: 'final' },
  },
});

