import { assign, setup } from 'xstate';

type Event = { type: 'chosen'; id: string } | { type: 'next' } | { type: 'submit' };
const machine = setup({
  types: { context: {} as { accountId?: string }, events: {} as Event },
  actions: {
    assignAccount: assign(({ event }) => ({
      accountId: event.type === 'chosen' ? event.id : undefined,
    })),
  },
  guards: { amountValid: ({ context }) => Boolean(context.accountId) },
}).createMachine({
  context: { accountId: undefined },
  initial: 'select',
  states: {
    select:  { on: { chosen: { target: 'amount', actions: 'assignAccount' } } },
    amount:  { on: { next:   { target: 'confirm', guard: 'amountValid' } } },
    confirm: { on: { submit: 'done' } },
    done:    { type: 'final' },
  },
});

type Step = { kind: 'select' } | { kind: 'amount'; id: string } | { kind: 'confirm' };

type Handlers = { [K in Step['kind']]: (s: Step, e: Event) => Step | undefined };

const table: Handlers = {
  select:  (_s, e) => (e.type === 'chosen' ? { kind: 'amount', id: e.id } : undefined),
  amount:  (s, e) => (e.type === 'next' && s.kind === 'amount' && valid(s.id)
                        ? { kind: 'confirm' } : undefined),
  confirm: (_s, e) => (e.type === 'submit' ? undefined : undefined),  // terminal step
};

export const step = (s: Step, e: Event): Step | undefined => table[s.kind](s, e);
